-- ============================================================
-- SEED: Módulo 10 — Modais Básicos (A2)
-- ============================================================
DO $$
DECLARE cid TEXT;
BEGIN
  SELECT id INTO cid FROM contents WHERE id = 'modais-basicos';
  IF cid IS NULL THEN RAISE EXCEPTION 'Módulo modais-basicos não encontrado'; END IF;

  INSERT INTO exercises (content_id, block_number, exercise_number, type, question, answer, options, explanation, difficulty) VALUES

  -- BLOCK 1: can/can't - ability
  (cid,1,1,'gap_fill','She ___ speak three languages fluently.','can',NULL,'"Can" expresses present ability. Subject + can + base verb.','easy'),
  (cid,1,2,'gap_fill','He ___ (not) swim, so he never goes to the beach.','can''t',NULL,'"Can''t" (cannot) = lack of ability.','easy'),
  (cid,1,3,'multiple_choice','Choose the correct sentence about ability.','She can read academic texts in French and Spanish.','["She can reads academic texts in French.","She cans read academic texts in French.","She can read academic texts in French and Spanish.","She can to read academic texts in French."]','Can + base verb (never add -s or "to" after can).','easy'),
  (cid,1,4,'gap_fill','___ you explain the difference between these two theories?','Can',NULL,'"Can" for requests and polite questions about ability.','easy'),
  (cid,1,5,'gap_fill','The computer ___ (not) process that amount of data simultaneously.','can''t',NULL,'"Can''t" for inability (machines, people, systems).','easy'),
  (cid,1,6,'multiple_choice','Which sentence uses "can" correctly for ability?','I can understand the lecture, but I can''t follow the technical vocabulary.','["I can understands the lecture.","I can understanding the lecture.","I can understand the lecture, but I can''t follow the technical vocabulary.","I am can understand the lecture."]','Can + base verb; can''t + base verb.','easy'),
  (cid,1,7,'gap_fill','With enough practice, anyone ___ learn to write well in academic English.','can',NULL,'"Can" for general possibility/ability.','easy'),

  -- BLOCK 2: could - past ability / polite requests
  (cid,2,8,'gap_fill','When she was young, she ___ memorize entire poems.','could',NULL,'"Could" for past ability (no longer possible now).','easy'),
  (cid,2,9,'multiple_choice','Choose the correct form for a polite request.','Could you please review my essay before the deadline?','["Can you please review my essay (less formal)?","Could you please review my essay before the deadline?","Might you please review my essay?","Should you please review my essay?"]','"Could" is more polite than "can" for requests.','medium'),
  (cid,2,10,'gap_fill','He ___ (not) attend the lecture yesterday because of illness.','couldn''t',NULL,'"Couldn''t" for past inability.','easy'),
  (cid,2,11,'multiple_choice','Which sentence uses "could" for PAST ABILITY?','As a child, she could solve complex math problems.','["She could come to tomorrow''s seminar (future request/possibility).","As a child, she could solve complex math problems.","Could you send me the research paper? (polite request)","If he tried harder, he could improve (conditional)."]','"Could" for ability that existed in the past.','medium'),
  (cid,2,12,'gap_fill','___ you tell me where the library is, please?','Could',NULL,'"Could you...?" = polite request.','easy'),
  (cid,2,13,'multiple_choice','Which is MORE polite?','Could I borrow your dictionary?','["Can I borrow your dictionary?","Could I borrow your dictionary?"]','"Could" is more formal and polite than "can" for requests.','easy'),
  (cid,2,14,'gap_fill','Before the internet, researchers ___ only access information through physical libraries.','could',NULL,'"Could" for past ability that is now obsolete.','medium'),

  -- BLOCK 3: may/might - possibility
  (cid,3,15,'gap_fill','She ___ be in the library — I''m not sure.','may / might',NULL,'"May" and "might" both express uncertainty/possibility. Either is correct.','easy'),
  (cid,3,16,'multiple_choice','Which word expresses LESS certainty about possibility?','might','["will","should","might","must"]','"Might" expresses lower possibility/certainty than "may" or "will".','medium'),
  (cid,3,17,'gap_fill','The experiment results ___ (might) vary depending on the conditions.','might',NULL,'"Might" for academic possibility — results may or may not vary.','easy'),
  (cid,3,18,'multiple_choice','Choose the correct sentence expressing possibility.','The increase in temperature may affect crop production in tropical regions.','["The increase in temperature will definitely affect crop production (certain).","The increase in temperature may affect crop production in tropical regions.","The increase in temperature might affecting crop production.","The increase in temperature can affect crop production (ability, not possibility)."]','"May" for academic possibility/hedging.','medium'),
  (cid,3,19,'gap_fill','This new approach ___ (might) not solve the problem entirely, but it ___ (may) reduce its impact.','might / may',NULL,'Both "might not" and "may" for varying degrees of possibility.','medium'),
  (cid,3,20,'multiple_choice','Which word is correct in academic hedging: "The data suggests that rising sea levels ___ threaten coastal cities."','may','["will (too certain)","should (obligation)","may","must (too strong)"]','"May" for academic hedging — acknowledging uncertainty.','hard'),
  (cid,3,21,'gap_fill','There ___ be a connection between these two variables, but further research is needed.','may / might',NULL,'"May/might" for speculative academic statements.','medium'),

  -- BLOCK 4: must/mustn't - obligation and prohibition
  (cid,4,22,'gap_fill','All students ___ submit their assignments before midnight on Friday.','must',NULL,'"Must" for strong obligation/requirement.','easy'),
  (cid,4,23,'gap_fill','You ___ (not) use a phone during the examination.','must not / mustn''t',NULL,'"Must not/mustn''t" for prohibition — something is not allowed.','easy'),
  (cid,4,24,'multiple_choice','Choose the sentence expressing PROHIBITION with "must not".','Students must not plagiarize any part of their work.','["Students must plagiarize any part of their work (wrong meaning).","Students must not plagiarize any part of their work.","Students mustn''t to plagiarize any part of their work.","Students must not to plagiarize any part of their work."]','Must not + base verb (no "to") for prohibition.','medium'),
  (cid,4,25,'gap_fill','Researchers ___ report all conflicts of interest before publishing.','must',NULL,'"Must" for ethical/institutional obligation.','easy'),
  (cid,4,26,'multiple_choice','What does "You must not take photographs in this lab" mean?','Taking photographs is prohibited here.','["You are not required to take photographs.","Taking photographs is prohibited here.","You are unable to take photographs.","Taking photographs is possible but not required."]','"Must not" = prohibition, not absence of obligation.','medium'),
  (cid,4,27,'gap_fill','The participants ___ (not) be informed of the study''s hypothesis before the experiment begins.','must not / mustn''t',NULL,'"Must not" for research ethics prohibition.','medium'),
  (cid,4,28,'multiple_choice','Choose the correct sentence.','You must bring your student ID to the exam; you must not bring notes.','["You must to bring your ID; you must not to bring notes.","You must bring your student ID to the exam; you must not bring notes.","You must brings your ID; you must not brings notes.","You must bringing your ID; you must not bringing notes."]','Must + base verb; must not + base verb.','easy'),

  -- BLOCK 5: should/shouldn't - advice
  (cid,5,29,'gap_fill','You ___ review all your vocabulary notes before the TOEFL listening section.','should',NULL,'"Should" for advice and recommendations.','easy'),
  (cid,5,30,'gap_fill','She ___ (not) rely on translation tools for academic writing.','shouldn''t',NULL,'"Shouldn''t" for negative advice.','easy'),
  (cid,5,31,'multiple_choice','Which sentence gives the best academic advice using "should"?','Students should engage critically with sources rather than simply summarizing them.','["Students should to engage critically with sources.","Students should engaging critically with sources.","Students should engage critically with sources rather than simply summarizing them.","Students shoulds engage critically with sources."]','Should + base verb for advice.','medium'),
  (cid,5,32,'gap_fill','Researchers ___ carefully consider the ethical implications of their methodology.','should',NULL,'"Should" for academic best practice recommendations.','medium'),
  (cid,5,33,'multiple_choice','What is the function of "should" in: "The government should invest more in public education."?','Recommendation/advice','["Certainty","Prohibition","Recommendation/advice","Past ability"]','"Should" = advice or recommendation.','easy'),
  (cid,5,34,'gap_fill','You ___ (not) start writing your essay before reading all the sources.','shouldn''t',NULL,'"Shouldn''t" = it is not advisable to...','easy'),
  (cid,5,35,'multiple_choice','Choose the sentence where "should" expresses a MORAL OBLIGATION.','We should treat all research participants with dignity and respect.','["She should arrive at 9 a.m. (expectation).","We should treat all research participants with dignity and respect.","The lecture should last an hour (expectation/prediction).","You should take the earlier bus (practical advice)."]','"Should" for moral obligation/duty.','hard'),

  -- BLOCK 6: have to vs must
  (cid,6,36,'gap_fill','She ___ (have to) submit three recommendation letters with her application.','has to',NULL,'"Have to" for external obligation — required by rules/others.','medium'),
  (cid,6,37,'multiple_choice','What is the key difference between "must" and "have to"?','Must = internal/personal obligation; have to = external obligation imposed by rules or others.','["Must is more polite than have to","Must = internal/personal obligation; have to = external obligation imposed by rules or others.","Must is only used for prohibition","Have to and must are always interchangeable"]','"Must" comes from internal authority; "have to" from external rules.','hard'),
  (cid,6,38,'gap_fill','Students ___ (have to) purchase a new edition of the textbook — the old one is no longer available.','have to',NULL,'"Have to" for obligation imposed by external circumstances.','medium'),
  (cid,6,39,'multiple_choice','Choose "must" or "have to": "The deadline is fixed by the department — all students ___ submit by 5 p.m."','have to','["must (internal obligation — student decides)","have to (external rule imposed by department)","should","can"]','"Have to" for obligation imposed externally by the department.','hard'),
  (cid,6,40,'gap_fill','I feel strongly about this — I ___ speak to the professor about the grading.','must',NULL,'"Must" for personal internal obligation/strong feeling.','hard'),
  (cid,6,41,'multiple_choice','In the past tense, which form is correct?','Yesterday, I had to rewrite the entire introduction.','["Yesterday, I must rewrite the entire introduction.","Yesterday, I had to rewrite the entire introduction.","Yesterday, I must have rewritten the entire introduction.","Yesterday, I have to rewrite the entire introduction."]','"Must" has no past form — use "had to" for past obligation.','hard'),
  (cid,6,42,'gap_fill','He ___ (not/have to) retake the exam because he passed with distinction.','didn''t have to',NULL,'"Didn''t have to" = it was not necessary (but it wasn''t forbidden). No obligation.','hard'),

  -- BLOCK 7: need to
  (cid,7,43,'gap_fill','You ___ (need to) practice all four TOEFL skills equally.','need to',NULL,'"Need to" = it is necessary to... (similar to "have to").','easy'),
  (cid,7,44,'multiple_choice','What does "She doesn''t need to resubmit the form" mean?','Resubmitting is not necessary.','["Resubmitting is forbidden.","Resubmitting is not necessary.","She cannot resubmit the form.","She should resubmit the form."]','"Don''t need to" = not necessary (no obligation). Compare: must not = prohibition.','medium'),
  (cid,7,45,'gap_fill','Researchers ___ (need to) obtain ethical approval before conducting studies with human subjects.','need to',NULL,'"Need to" for necessary steps/requirements in academic research.','medium'),
  (cid,7,46,'multiple_choice','Choose the correct sentence with "need to".','The students need to improve their academic writing before the final submission.','["The students need improve their academic writing.","The students need to improving their academic writing.","The students need to improve their academic writing before the final submission.","The students needs to improve their academic writing."]','Need to + base verb (infinitive without to after need to).','medium'),
  (cid,7,47,'gap_fill','She ___ (not/need to) rewrite the whole essay — just the conclusion.','doesn''t need to',NULL,'"Doesn''t need to" = it is not necessary for her.','medium'),
  (cid,7,48,'multiple_choice','What is the difference between "needn''t resubmit" and "mustn''t resubmit"?','Needn''t = not necessary; mustn''t = forbidden.','["They mean the same thing","Needn''t = not necessary; mustn''t = forbidden.","Needn''t is more formal","Mustn''t = not necessary; needn''t = forbidden"]','"Needn''t" = no obligation; "mustn''t" = prohibition. Critical distinction.','hard'),
  (cid,7,49,'gap_fill','You ___ (need to) understand the difference between modals to avoid common TOEFL errors.','need to',NULL,'"Need to" for necessary knowledge/skills.','easy'),

  -- BLOCK 8: mixed modals review
  (cid,8,50,'multiple_choice','Choose the correct modal: "Participants ___ withdraw from the study at any time without penalty."','may','["must","may","should","can''t"]','"May" for permission — participants are permitted to withdraw.','medium'),
  (cid,8,51,'gap_fill','The new evidence ___ (might) challenge current theories about dark matter.','might',NULL,'"Might" for academic speculation/possibility.','medium'),
  (cid,8,52,'multiple_choice','Identify the error: "She musts submit her application by tomorrow."','musts should be must','["She should be Her","musts should be must","submit should be submits","application should be applications"]','Modals never take -s in any person. Must, not musts.','easy'),
  (cid,8,53,'gap_fill','You ___ (not/must) use another student''s work and present it as your own.','must not / mustn''t',NULL,'"Must not" for academic integrity prohibition (plagiarism).','easy'),
  (cid,8,54,'multiple_choice','Choose the modal that expresses PAST INABILITY.','She couldn''t understand the professor''s accent at first.','["She can''t understand the accent at first (present).","She couldn''t understand the professor''s accent at first.","She mustn''t understand the accent at first.","She didn''t can understand the accent at first."]','"Couldn''t" for past inability.','medium'),
  (cid,8,55,'gap_fill','All international students ___ (have to) demonstrate English proficiency before enrollment.','have to',NULL,'"Have to" for externally imposed requirement.','medium'),
  (cid,8,56,'multiple_choice','Which sentence correctly expresses advice?','You should diversify your sources to strengthen your argument.','["You must diversify your sources (obligation, not advice).","You can diversify your sources (ability, not advice).","You should diversify your sources to strengthen your argument.","You might diversify your sources (weak possibility, not advice)."]','"Should" for advice and academic recommendations.','medium'),

  -- BLOCK 9: TOEFL academic contexts
  (cid,9,57,'multiple_choice','[TOEFL Reading] In the passage, the author uses "may" to indicate that the findings ___','are possible but not certain','["are definitely true","are impossible","are possible but not certain","are required"]','Academic "may" signals hedging — acknowledging uncertainty.','medium'),
  (cid,9,58,'gap_fill','[TOEFL Listening] The professor explains that researchers ___ (must) distinguish between correlation and causation; failure to do so ___ (can) lead to misleading conclusions.','must / can',NULL,'"Must" for obligation; "can" for possibility of negative outcome.','hard'),
  (cid,9,59,'multiple_choice','[TOEFL Reading] Which modal best completes this academic sentence? "These results ___ be interpreted with caution due to the small sample size."','should','["must (too strong — prohibition implied)","can","should","will"]','"Should" for academic recommendations and caution.','hard'),
  (cid,9,60,'gap_fill','[TOEFL Listening] The lecturer states: "Students ___ (must) read the original texts, not only secondary sources; relying solely on summaries ___ (might) lead to misrepresentation."','must / might',NULL,'"Must" for strong academic obligation; "might" for speculative risk.','hard'),
  (cid,9,61,'multiple_choice','[TOEFL Reading] The passage says governments "may" implement new carbon taxes. What does this imply?','It is possible but not certain that governments will implement these taxes.','["Governments are required to implement the taxes.","Governments are prohibited from implementing the taxes.","It is possible but not certain that governments will implement these taxes.","Governments will definitely implement the taxes."]','"May" = possibility without certainty.','hard'),
  (cid,9,62,'gap_fill','[TOEFL Reading] "The long-term effects of microplastics on human health ___ (might) be more severe than initially estimated, according to recent studies."','might',NULL,'"Might" for speculative academic claims with hedging language.','hard'),
  (cid,9,63,'multiple_choice','[TOEFL Listening] The professor says: "Scholars ___ not ignore conflicting evidence when building their theoretical frameworks." Which modal is this?','should not','["must not (prohibition)","might not","should not","cannot"]','"Should not" in academic context = recommendation to avoid an action.','hard'),

  -- BLOCK 10: TOEFL production tasks
  (cid,10,64,'multiple_choice','[TOEFL Reading] Which sentence uses modals most effectively in academic argumentation?','Policymakers must address income inequality; failure to do so may undermine social cohesion.','["Policymakers can address income inequality; failure to do so might undermine cohesion (weaker).","Policymakers must address income inequality; failure to do so may undermine social cohesion.","Policymakers should can address income inequality; failure to do so might undermine cohesion.","Policymakers have to address income inequality; failure might will undermine cohesion."]','"Must" for strong obligation; "may" for academic possibility.','hard'),
  (cid,10,65,'gap_fill','[TOEFL Reading] To ensure validity, researchers ___ (must) control all variables; additionally, they ___ (should) document all procedures, and results ___ (may) need to be independently verified.','must / should / may',NULL,'Multiple modals in academic methodology: obligation (must), advice (should), possibility (may).','hard'),
  (cid,10,66,'multiple_choice','[TOEFL Speaking — 45s] Which response most effectively uses modals to discuss academic integrity?','Students must not plagiarize; they should always cite their sources, and if they are unsure, they can consult a writing center tutor.','["Students cannot plagiarize; they must always cite their sources.","Students must not plagiarize; they should always cite their sources, and if they are unsure, they can consult a writing center tutor.","Students should not plagiarize; they might cite their sources always.","Students mustn''t to plagiarize; they should to always cite."]','Must not (prohibition), should (advice), can (ability/option).','hard'),
  (cid,10,67,'production','[TOEFL Speaking — 45s] Discuss the responsibilities of a university student in academic research. Use at least 5 different modals: must, should, can, may, and have to. Explain what students must do, what they should avoid, what they can choose to do, and what they may encounter.','',NULL,'Practice using must (obligation), should (advice), can (ability), may (possibility), have to (external rule).','hard'),
  (cid,10,68,'production','[TOEFL Writing] Write a paragraph (4-5 sentences) about the ethical obligations of researchers. Include: must for obligations, must not for prohibitions, should for recommendations, and may/might for uncertain outcomes of unethical research.','',NULL,'Academic writing uses a range of modals for obligation, prohibition, advice, and possibility.','hard'),
  (cid,10,69,'multiple_choice','[TOEFL Writing] Which paragraph opening best uses modals in an academic essay about public health?','Governments must prioritize preventive healthcare; they should allocate sufficient funding, and they may need to regulate unhealthy food products.','["Governments can prioritize preventive healthcare; they might allocate funding; they must regulate food.","Governments must prioritize preventive healthcare; they should allocate sufficient funding, and they may need to regulate unhealthy food products.","Governments should must prioritize healthcare; they can allocate funding.","Governments have to must prioritize healthcare; they should regulate food."]','Must (strong obligation), should (recommendation), may (possible necessity).','hard'),
  (cid,10,70,'production','[TOEFL Writing] Write a 5-sentence academic paragraph on the role of governments in addressing climate change. Use at least one each of: must, should, can, may, and either have to or need to. Vary your sentence structures and avoid repeating the same subject.','',NULL,'Demonstrate flexible use of all core modals in a coherent academic argument about policy.','hard')

  ON CONFLICT (content_id, block_number, exercise_number) DO NOTHING;
END $$;
